{
  "components": [
    {
      "type": "obligation",
      "quote": "The vice president is required to step in and take on all the presidial duties when the president is unable to.",
      "gist": "Vice president must assume presidential duties if the president is unavailable."
    },
    {
      "type": "obligation",
      "quote": "The Federal Council may also assign the vice president presidential powers.",
      "gist": "Federal Council can grant vice president additional presidential powers."
    },
    {
      "type": "claim",
      "quote": "Presidents of the Swiss Confederation have special representational duties during their year of office.",
      "gist": "Swiss Confederation presidents have specific representational duties during their term."
    },
    {
      "type": "condition",
      "quote": "Traditionally they give a speech at New Year and on Swiss National Day on 1 August, which is broadcast on radio and television.",
      "gist": "Swiss presidents traditionally give speeches on New Year and Swiss National Day (1 August), broadcast on radio and TV."
    },
    {
      "type": "obligation",
      "quote": "They also welcome the diplomatic corps – all foreign ambassadors to Switzerland – at a New Year’s reception in the Federal Palace.",
      "gist": "Swiss presidents must host a New Year's reception for foreign ambassadors at the Federal Palace."
    }
  ]
}
